// Extrai o array de empresas retornado pela agregação
const response = $input.first().json;
const companies = response.companies || [];

return companies.map(c => ({ json: c }));

// Monta a mensagem de notificação SEM chamar LLM.
// O valor aqui é o dado agregado já pago/processado, não geração de texto criativo.
const items = [];

for (const item of $input.all()) {
  const c = item.json;

  const message =
    `🎯 *Radar de Empresas Recorrentes*\n\n` +
    `*${c.company}* apareceu em *${c.occurrences}* vagas com score >= 70 ` +
    `nos últimos 28 dias.\n\n` +
    `Última vaga: *${c.latest_job_title}*\n` +
    `Score mais alto: ${c.best_score}/100\n` +
    `Link: ${c.latest_job_url}\n\n` +
    `💡 Sugestão: considere contato direto com um recrutador dessa empresa ` +
    `no LinkedIn, em vez de só aplicar via formulário novamente.`;

  items.push({ json: { ...c, message } });
}

return items;

// Extrai o array de vagas retornado pela busca
const searchResponse = $input.first().json;
const jobs = searchResponse.jobs || [];

return jobs.map(job => ({
  json: {
    job_url: job.job_url,
    title: job.title,
    company: job.company,
    job_id: job.job_id
  }
}));

